let workAssignee='';
import {annualDashboard,incidentList,referenceKpis,noticesPage,statisticsPage} from '/dashboard.js';
import {teams as partOptions,selectWorks,metrics,statuses,monthRange,monthlyHighlights,periodFlow,classifyWorkStatus,yearRange,incidentWorks,filterByAssignee,sortWorkList} from '/lib.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let annualPerson='',dashboardYear='',state, page='대시보드', search='',statusFilter='',kind='',period='month',filters={},upload=null,reportDraft='',busy=false;
const menu=[['▦','대시보드'],['▤','업무현황'],['☷','업무 목록'],['↥','엑셀 업로드'],['▧','보고서 보관함'],['▥','통계 분석'],['▣','장비지원 분석'],['▧','게시판 / 공지'],['✦','AI 업무분석'],['⚙','관리자 설정']];
const color={'완료':'teal','진행':'blue','접수':'purple','예정':'amber','보류':'red','취소':'muted'};
const badge=s=>`<span class="badge ${color[s]||'muted'}"><i></i>${esc(s)}</span>`;
const opt=(values,selected,blank='')=>(blank?`<option value="">${blank}</option>`:'')+values.map(v=>`<option ${v===selected?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('');
function notify(message,error=false){const e=$('#toast');e.textContent=message;e.className=error?'visible error':'visible';clearTimeout(notify.timer);notify.timer=setTimeout(()=>e.className='',5000);}
async function api(url,method='GET',data){const r=await fetch(url,{method,headers:{'Content-Type':'application/json','X-IT-Token':state?.token||''},body:data===undefined?undefined:JSON.stringify(data)});const v=await r.json();if(!r.ok){const error=Error(v.error||'요청에 실패했습니다.');error.status=r.status;throw error;}return v;}
async function refresh(){try{state=await api('/api/state');}catch(e){if(e.status===401){state=null;await loginView();return;}throw e;}state.works=state.works.map(w=>({...w,status:classifyWorkStatus(w.status)}));if(!filters.from)setPeriod('month');render();}
function setPeriod(value){period=value;const now=state.today;let from,to=now;if(value==='year'){filters={...filters,...yearRange(now.slice(0,4),now)};return;}if(value==='month'){from=now.slice(0,7)+'-01';to=new Date(Date.UTC(+now.slice(0,4),+now.slice(5,7),0)).toISOString().slice(0,10);}else if(value==='week'){const d=new Date(now+'T00:00:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));from=d.toISOString().slice(0,10);d.setUTCDate(d.getUTCDate()+6);to=d.toISOString().slice(0,10);}else return;filters={...filters,from,to,asOf:now,basis:filters.basis||'activity'};}
const effectiveFilters=()=>({...filters,q:search,status:statusFilter,kind,...(period==='month'||period==='year'||page==='업무현황'?{mode:'flow'}:{})});
const selected=()=>{const rows=period==='month'||period==='year'||page==='업무현황'?periodFlow(state.works,effectiveFilters()).rows:selectWorks(state.works,effectiveFilters());return page==='업무 목록'?sortWorkList(filterByAssignee(rows,workAssignee)):rows;};
function previousWorks(){if(period==='month'){const d=new Date(filters.from+'T00:00:00Z');d.setUTCMonth(d.getUTCMonth()-1);const range=monthRange(d.toISOString().slice(0,7),state.today);return periodFlow(state.works,{...effectiveFilters(),...range}).rows;}const start=new Date(filters.from+'T00:00:00Z'),end=new Date(filters.to+'T00:00:00Z'),days=(end-start)/86400000+1;const to=new Date(start-86400000).toISOString().slice(0,10),from=new Date(start-days*86400000).toISOString().slice(0,10);return selectWorks(state.works,{...filters,from,to,asOf:to});}
function render(){
 const works=selected(),m=metrics(works);
 $('#app').innerHTML=`<aside><div class="brand"><span class="brandmark">IT<span>✦</span></span><div>IT WORKSPACE<small>전산팀 업무관리</small></div></div><div class="side-label">WORKSPACE</div><nav>${menu.filter(([,name])=>state.currentUser.role==='admin'||!['관리자 설정','엑셀 업로드'].includes(name)).map(([icon,name])=>`<button class="nav ${page===name?'active':''}" data-nav="${name}"><span>${icon}</span>${name}${name==='엑셀 업로드'?'<b>Excel</b>':''}</button>`).join('')}</nav><div class="side-bottom"><div class="local-status"><i></i> 로컬 파일 저장 모드<small>데이터가 이 PC에 보관됩니다</small></div><div class="profile"><span class="avatar">전</span><div>${esc(state.currentUser.name)}<small>${roleName(state.currentUser.role)}</small></div></div></div></aside><main><header><span>워크스페이스 <b>/</b> ${page}</span><div><span class="connection"><i></i> 파일 저장 연결됨</span><span class="header-date">${esc(state.today.replaceAll('-','.'))}</span><button class="notification-button" data-nav="게시판 / 공지" aria-label="공지사항">♧<b>${(state.notices||[]).filter(n=>!n.archived).length}</b></button><button class="text-button" id="change-password">비밀번호 변경</button><button class="text-button" id="logout">로그아웃</button><button class="icon-button" id="refresh" aria-label="새로고침">↻</button></div></header><section class="content"><div class="page-heading"><div><div class="eyebrow">IT OPERATIONS / ${page==='대시보드'?'OVERVIEW':'WORKSPACE'}</div><h1>${page==='대시보드'?'전산팀 업무관리 대시보드':esc(page)}</h1><p>${page==='대시보드'?'한 해의 접수·완료 실적과 잔여 과제를 확인하세요. 상세 내역은 업무현황에서 조회합니다.':'업무 데이터와 원본 근거를 함께 확인하고 관리하세요.'}</p></div><div class="actions"><button id="upload-nav">↥ 엑셀 업로드</button><button class="primary" id="new-work">＋ 업무 등록</button></div></div>${['대시보드','업무현황','업무 목록','통계 분석','장비지원 분석'].includes(page)?(page==='대시보드'?annualFilterBar():filterBar()):''}<div id="view">${page==='대시보드'?dashboard(works,m):page==='업무현황'?(period==='month'?monthly(works,m):weekly(works,m)):page==='업무 목록'?workList(works):page==='엑셀 업로드'?uploadView():page==='보고서 보관함'?reportsView():page==='관리자 설정'?settingsView()+accountSettingsPanel()+excelSettingsPanel():page==='게시판 / 공지'?noticesPage(state):page==='통계 분석'?flowStatistics(works):page==='장비지원 분석'?flowStatistics(works,true):aiView()}</div><footer><span>IT WORKSPACE <b>·</b> 함께 관리하는 전산팀 업무</span><span>JSON 파일 저장 · 리비전 ${state.revision} · 외부 전송 없음</span></footer></section></main>`;
 bind();
 applyPermissions();
}
function filterBar(){return `<div class="filter-bar"><div class="segmented">${page==='업무 목록'?`<button data-period="year" class="${period==='year'?'selected':''}">연간</button>`:''}<button data-period="week" class="${period==='week'?'selected':''}">주간</button><button data-period="month" class="${period==='month'?'selected':''}">월간</button><button data-period="custom" class="${period==='custom'?'selected':''}">직접 선택</button></div>${period==='year'?workYearSelect():period==='month'?`<label class="month-picker">조회 월<input type="month" id="report-month" aria-label="조회 월" value="${filters.from.slice(0,7)}"></label>`:`<div class="date-range"><input aria-label="기간 시작" type="date" id="from" value="${filters.from}"><span>—</span><input aria-label="기간 끝" type="date" id="to" value="${filters.to}"></div>`}<label class="part-filter-label">파트구분 <select id="team" aria-label="파트 필터">${opt(partOptions,filters.team,'전체선택')}</select></label>${page==='업무 목록'?workAssigneeSelect():''}${period==='month'||period==='year'||page==='업무현황'?'<span class="flow-basis">접수일 · 완료일 · 기준일 상태 통합</span>':`<select id="basis" aria-label="기간 집계 기준">${[['activity','활동일 기준'],['created','등록일 기준'],['completed','완료 전이일 기준']].map(([v,n])=>`<option value="${v}" ${filters.basis===v?'selected':''}>${n}</option>`).join('')}</select>`}${period==='month'||period==='year'?`<span class="asof">상태 기준일 ${filters.asOf}</span>`:`<label class="asof">기준일 <input id="asOf" aria-label="상태 기준일" type="date" value="${filters.asOf}"></label>`}</div><div class="criteria"><span><i></i> ${filters.from} ~ ${filters.to} · ${period==='month'||period==='year'||page==='업무현황'?'전기 이월·기간 접수·완료·기준일 미완료':filters.basis==='activity'?'기간 내 활동한 고유 업무':filters.basis==='created'?'기간 내 등록된 고유 업무':'기간 내 완료 전이가 있는 고유 업무'} · ${filters.asOf} 시점 상태</span><span>공동담당은 고유업무 1건으로 집계</span></div>`;}
function kpis(m){return referenceKpis(m,metrics(previousWorks()));}
function dashboard(){const range=yearRange(dashboardYear||state.today.slice(0,4),state.today);return annualDashboard(state,{...range,team:filters.team||'',person:annualPerson},rows=>alerts(rows,range.asOf));}
function teamBars(works){const rows=state.settings.teams.map(t=>({t,m:metrics(works.filter(w=>w.assignees.some(a=>a.team===t)))})),max=Math.max(1,...rows.map(r=>r.m.total));return rows.map(({t,m})=>`<button class="bar-row" data-team="${t}"><span>${t}</span><div class="bar-track">${[['완료','teal'],['진행','blue'],['기타','slate']].map(([s,c])=>{const n=s==='기타'?m.total-m['완료']-m['진행']:m[s];return `<div class="bar-segment bg-${c}" style="width:${n/max*100}%">${n?`<span>${n}</span>`:''}</div>`;}).join('')}</div><b>${m.total}<small>건</small></b></button>`).join('');}
function trendChart(){const start=new Date(filters.from+'T00:00:00Z'),end=new Date(filters.to+'T00:00:00Z');const days=Math.max(1,(end-start)/86400000+1),step=Math.max(1,Math.ceil(days/5));const points=[];for(let i=0;i<5;i++){const a=new Date(+start+i*step*86400000),b=new Date(Math.min(+end,+a+(step-1)*86400000));if(a>end)break;const from=a.toISOString().slice(0,10),to=b.toISOString().slice(0,10);const base=state.works.filter(w=>(!filters.team||w.assignees.some(a=>a.team===filters.team))&&(!kind||w.kind===kind));const asOf=to<filters.asOf?to:filters.asOf;points.push({label:from.slice(5).replace('-','.'),new:selectWorks(base,{from,to,asOf,basis:'created'}).length,done:selectWorks(base,{from,to,asOf,basis:'completed'}).length,open:selectWorks(base,{to:asOf,asOf,basis:'created'}).filter(w=>w.status!=='완료').length});}const max=Math.max(1,...points.flatMap(p=>[p.new,p.done,p.open]));const line=(key,c)=>`<polyline fill="none" stroke="${c}" stroke-width="3" stroke-linejoin="round" points="${points.map((p,i)=>`${45+i*100},${170-p[key]/max*135}`).join(' ')}"/>${points.map((p,i)=>`<circle cx="${45+i*100}" cy="${170-p[key]/max*135}" r="4" fill="${c}"><title>${p.label} ${key==='new'?'신규':key==='done'?'완료':'미완료'} ${p[key]}건</title></circle>`).join('')}`;return `<div class="trend"><svg viewBox="0 0 490 210" role="img" aria-label="신규 완료 미완료 업무 추세">${[0,1,2,3].map(i=>`<line x1="35" x2="460" y1="${35+i*45}" y2="${35+i*45}" stroke="#304155" stroke-dasharray="3 5"/><text x="5" y="${40+i*45}">${Math.round(max*(3-i)/3)}</text>`).join('')}${line('open','#d9ae66')}${line('new','#729eef')}${line('done','#21c3bc')}${points.map((p,i)=>`<text x="${45+i*100}" y="200" text-anchor="middle">${p.label}</text>`).join('')}</svg></div>`;}
function distribution(works){const counts=state.settings.categories.map(c=>({name:c,n:works.filter(w=>w.category===c).length})).filter(c=>c.n).sort((a,b)=>b.n-a.n);const palette=['#21c3bc','#729eef','#a995e9','#d9ae66','#647c94'];let acc=0;const gradient=counts.map((c,i)=>{const from=acc;acc+=c.n/Math.max(1,works.length)*100;return `${palette[i%5]} ${from}% ${acc}%`;}).join(',');return `<div class="distribution"><div class="donut" style="background:${counts.length?`conic-gradient(${gradient})`:'#304155'}"><div><strong>${works.length}</strong><span>고유 업무</span></div></div><div class="distribution-list">${counts.length?counts.slice(0,6).map((c,i)=>`<div><span><i style="background:${palette[i%5]}"></i>${esc(c.name)}</span><b>${c.n}<small>건</small></b></div>`).join(''):'<p class="muted">아직 등록된 업무가 없습니다.</p>'}</div></div>`;}
function alerts(works,asOf=filters.asOf){const items=works.filter(w=>w.status==='보류'||w.due&&w.due<asOf&&w.status!=='완료').slice(0,3);return items.length?items.map(w=>`<button class="alert-item" data-work="${w.id}"><span class="alert-dot ${w.status==='보류'?'amber':'red'}">!</span><div><b>${esc(w.title)}</b><small>${w.status==='보류'?'보류 · '+esc(w.reason):'목표일 경과 · '+esc(w.due)} · ${esc(w.assignees[0].team)}</small></div><span>↗</span></button>`).join(''):'<div class="all-clear"><span>✓</span><div>확인이 필요한 지연·보류 업무가 없습니다.<small>목표일과 상태를 기준으로 확인합니다.</small></div></div>';}
function table(works){return `<div class="table-wrap"><table><thead><tr><th>업무명 / ID</th><th>파트 · 담당자</th><th>업무구분</th><th>상태</th><th>등록일</th><th>완료일</th><th>원본</th></tr></thead><tbody>${works.map(w=>`<tr><td><button class="work-title" data-work="${w.id}">${esc(w.title)}</button><small class="work-id">${w.id.slice(0,8)}${w.tags?' · '+esc(w.tags):''}</small></td><td>${esc([...new Set(w.assignees.map(a=>a.team))].join(' · '))}<small>${esc(w.assignees.map(a=>a.name).join(', '))}</small></td><td>${esc(w.category)}</td><td>${badge(w.status)}</td><td class="subtle">${w.created}</td><td class="subtle">${esc(w.completed)||'—'}</td><td><span class="source-label">${w.source?'XLSX · '+esc(w.source.row)+'행':'직접 입력'}</span></td></tr>`).join('')||'<tr><td colspan="7" class="empty">조회 조건에 해당하는 업무가 없습니다.</td></tr>'}</tbody></table></div>`;}
function emptyBanner(){return `<div class="empty-banner"><div><h2>우리 팀의 첫 업무를 연결해 보세요</h2><p>업무를 직접 등록하거나 엑셀 파일을 업로드할 수 있습니다.</p></div><button id="demo">예제 데이터로 둘러보기 →</button></div>`;}
function workList(works){return `<article class="panel"><div class="panel-head"><div><h2>업무 목록 <span class="teal">${works.length}</span></h2><p>최신 날짜순 · 완료 업무는 완료일, 예정·진행·보류 업무는 등록일 기준입니다.</p></div><button id="export">↓ CSV 내보내기</button></div><div class="table-controls"><input id="search" placeholder="업무명, 담당자, 태그 검색" value="${esc(search)}"><select id="status-filter">${opt([...statuses.filter(s=>s!=='접수'),'기타'],statusFilter,'전체 상태')}</select><select id="kind">${opt(['개발업무','장비지원'],kind,'전체 업무유형')}</select></div>${table(works)}</article>`;}
function weekly(works,m){const base=state.works.filter(w=>!filters.team||w.assignees.some(a=>a.team===filters.team));const newCount=selectWorks(base,{...filters,basis:'created'}).length,done=selectWorks(base,{...filters,basis:'completed'}).length,carry=selectWorks(base,{from:'0000-01-01',to:filters.from,asOf:filters.from,basis:'created'}).filter(w=>w.created<filters.from&&w.status!=='완료').length;return `${flowKpis(periodFlow(state.works,effectiveFilters()))}<div class="notice">이번 기간 신규 <b>${newCount}건</b> · 완료 전이 <b>${done}건</b> · 기간 시작 전 이월 미완료 <b>${carry}건</b></div><article class="panel"><div class="panel-head"><h2>파트별 주요 진행사항</h2><button id="export">↓ Excel용 CSV</button></div><div class="team-cards">${state.settings.teams.map(t=>`<section><h3>${t}<span>${works.filter(w=>w.assignees.some(a=>a.team===t)).length}건</span></h3>${works.filter(w=>w.assignees.some(a=>a.team===t)).slice(0,5).map(w=>`<button data-work="${w.id}">${badge(w.status)}<span>${esc(w.title)}</span></button>`).join('')||'<p class="muted">해당 업무 없음</p>'}</section>`).join('')}</div></article>`;}
function monthly(){
 const f=periodFlow(state.works,effectiveFilters()),teams=filters.team?[filters.team]:state.settings.teams;
 return `${flowKpis(f)}<article class="panel"><div class="panel-head"><div><h2>파트별 실적표</h2><p>접수일·완료일과 해당 기준일의 상태이력을 각각 적용합니다.</p></div><button id="create-report" class="primary">보고서 작성 및 확정 →</button></div><div class="table-wrap"><table><thead><tr><th>파트</th><th>전월 이월</th><th>당월 접수</th><th>당월 완료</th><th>${f.cutoff<filters.to?'기준일':'월말'} 미완료</th></tr></thead><tbody>${teams.map(t=>{const p=periodFlow(state.works,{...effectiveFilters(),team:t});return `<tr><td>${esc(t)}</td><td>${p.carry}건</td><td>${p.received}건</td><td class="teal">${p.completed}건</td><td class="amber">${p.remaining}건</td></tr>`;}).join('')}</tbody></table></div></article>${monthlyHighlightsTable(f.rows)}<div class="notice">완료는 완료일, 접수는 접수일, 이월·잔여는 당시 상태이력으로 계산합니다. 이후 완료돼도 과거 월말 미완료는 유지됩니다. 재오픈 업무는 당월 완료와 미완료에 모두 포함될 수 있습니다. 공동담당은 각 참여 파트에 표시됩니다.</div>`;
}
function flowKpis(f){return `<div class="flow-kpis">${[[period==='month'?'전월 이월':'전기 이월',f.carry,'기간 시작 전 미완료'],[period==='month'?'당월 접수':'기간 접수',f.received,'접수일 기준'],[period==='month'?'당월 완료':'기간 완료',f.completed,'완료일 기준'],[f.cutoff<filters.to?'기준일 미완료':period==='month'?'월말 미완료':'기간말 미완료',f.remaining,f.cutoff+' 시점 미완료']].map(([title,note,sub])=>`<div class="panel"><span>${title}</span><strong>${note}<small>건</small></strong><p>${sub}</p></div>`).join('')}</div>`;}
function flowStatistics(works,equipment=false){return (period==='month'?flowKpis(periodFlow(state.works,{...effectiveFilters(),...(equipment?{kind:'장비지원'}:{})})):'' )+statisticsPage(works,filters,state,equipment);}
function uploadView(){if(!upload)return `<div class="steps"><b>01 파일 선택</b><span>02 시트·컬럼 매핑</span><span>03 검증·중복 확인</span><span>04 반영 완료</span></div><article class="panel upload-panel"><div class="upload-icon">↥</div><h2>엑셀로 시작하는 업무관리</h2><p>기존 주간업무일지를 그대로 가져오세요.<br>시트와 컬럼을 확인한 뒤 필요한 행만 반영할 수 있습니다.</p><label class="primary file-label">파일 선택<input type="file" id="file" accept=".xlsx,.csv"></label><small>XLSX · UTF-8 CSV / 최대 10MB · 20,000행</small><p class="upload-help">병합된 헤더는 실제 제목 행 번호를 선택하세요.<br>빈 셀은 임의로 채우지 않으며, 담당자와 상태 매핑을 검토합니다.</p></article>${batchHistory()}`;if(upload.rows)return validationView();return mappingView();}
const fields=[['title','업무 제목 *'],['assignees','담당자 *'],['team','파트'],['status','상태'],['category','업무구분'],['created','등록일'],['completed','완료일'],['description','내용'],['reason','변경·보류 사유'],['externalId','외부 업무ID'],['week','주간구분']];
function defaultMap(sheet,header){const row=sheet.rows.find(r=>r.number===header)?.cells||[];const patterns={title:/^(업무명|제목|업무제목|업무내용|업무 제목)$/,assignees:/^(담당자|성명|이름)$/,team:/^(파트|소속)$/,status:/^(상태|진행상태|처리상태)$/,category:/^(업무구분|구분|분류)$/,created:/^(등록일|요청일|접수일)$/,completed:/^(완료일|처리일)$/,description:/^(내용|상세내용|조치내역)$/,reason:/^(사유|보류사유)$/,externalId:/^(업무ID|외부ID)$/,week:/^(주간구분|주차|주간 구분)$/};return Object.fromEntries(fields.map(([key])=>[key,row.findIndex(s=>patterns[key].test(String(s).trim()))]));}
function mappingView(){
 const sample=upload.sheets.find(s=>upload.selected?.includes(s.name))||upload.sheets[0];
 const header=upload.commonHeader||sample.rows[0]?.number||1;
 const cells=sample.rows.find(r=>r.number===header)?.cells||[];
 const map=upload.commonMap||defaultMap(sample,header);
 const availableWeeks=[...new Set(upload.sheets.filter(s=>upload.selected.includes(s.name)).flatMap(s=>s.rows.filter(r=>r.number>header).map(r=>String(r.cells[map.week]||'').replace(/\s/g,''))))].filter(s=>/^\d{1,2}월\d주(?:차)?$/.test(s)).sort((a,b)=>{const n=s=>{const m=s.match(/(\d+)월(\d+)/);return +m[1]*10+(+m[2]);};return n(b)-n(a);});
 return `<div class="steps"><span>01 파일 선택</span><b>02 공통 매핑 확인</b><span>03 검증·중복 확인</span><span>04 반영 완료</span></div><article class="panel"><div class="panel-head"><div><h2>${esc(upload.name)}</h2><p>같은 양식의 모든 개발자 시트에 아래 공통 매핑을 한 번에 적용합니다.</p></div><button id="upload-reset">다른 파일 선택</button></div><div class="mapping-meta"><label>주간 활동일 *<input type="date" id="upload-period" value="${upload.period||state.today}"></label><label>업무 유형<select id="upload-kind">${opt(['개발업무','장비지원'],upload.kind||'개발업무')}</select></label><label>상태 매핑<input id="status-map" placeholder="처리중=진행, 대기=접수" value="${esc(upload.statusText||'')}"></label></div><section class="sheet-section"><div class="notice"><label class="checkbox-label"><input type="checkbox" id="weekly-only" ${upload.weeklyOnly!==false?'checked':''}>선택 주차 + 예정 업무만 반영 (누적 파일)</label><label class="preset-status">반영 주차<input id="week-label" placeholder="예: 10월4주" value="${esc(upload.weekLabel||availableWeeks[0]||'')}"></label><p>주간구분이 선택 주차 또는 ‘예정’인 행과 상태가 ‘예정’인 행만 검증합니다. 과거 주차의 나머지 행과 보류 상태 행은 제외합니다. 파일의 가장 최근 주차를 기본 제안하므로 반영 전 확인하세요.</p></div><h3>반영할 시트 선택</h3><div class="sheet-selection-actions"><button type="button" id="select-all-sheets">모두 선택</button><button type="button" id="clear-all-sheets">선택 해제</button></div><p class="muted">통계 시트는 업무 등록에서 자동 제외됩니다.</p><div class="sheet-checks">${upload.sheets.map(sheet=>`<label><input type="checkbox" data-sheet="${esc(sheet.name)}" ${upload.selected?.includes(sheet.name)?'checked':''}>${esc(sheet.name)}<small>${sheet.rows.length}행</small></label>`).join('')}</div><div class="common-mapping-heading"><h3>공통 컬럼 매핑</h3><label>헤더 행<input type="number" min="1" max="20000" id="common-header" value="${header}"></label><label>담당자 확인<select id="assignee-source">${[['column','담당자 컬럼 사용'],['sheet','시트명 = 직원명']].map(([v,n])=>`<option value="${v}" ${(upload.assigneeSource||'column')===v?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="mapping-grid">${fields.filter(([key])=>key!=='team').map(([key,label])=>`<label>${label}<select data-common-map="${key}"><option value="-1">연결 안 함</option>${Array.from({length:Math.min(150,Math.max(cells.length,20,...Object.values(map).map(Number))+1)},(_,i)=>`<option value="${i}" ${Number(map[key])===i?'selected':''}>${i+1}열 · ${esc(cells[i]||'')}</option>`).join('')}</select></label>`).join('')}</div><div class="notice mapping-notice">파트는 관리자 설정의 직원별 소속 파트로 자동 반영됩니다. 엑셀의 파트 컬럼은 사용하지 않습니다.${state.settings.excelMapping?'<br>관리자에 저장된 공통 매핑을 불러왔습니다.':''}</div><details><summary>기준 시트 원본 미리보기 · ${esc(sample.name)} (처음 5행)</summary><div class="table-wrap"><table><tbody>${sample.rows.slice(0,5).map(r=>`<tr><th>${r.number}행</th>${r.cells.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details></section><div class="panel-actions"><button id="save-upload-mapping">공통 매핑을 관리자 설정에 저장</button><button id="validate-upload" class="primary">전체 선택 시트 검증 →</button></div></article>`;
}
function validationView(){const rows=upload.rows;return `<div class="steps"><span>01 파일 선택</span><span>02 시트·컬럼 매핑</span><b>03 검증·중복 확인</b><span>04 반영 완료</span></div><div class="notice">${upload.weeklyOnly?esc(upload.weekLabel)+' + 예정 업무만 검증합니다. 다른 과거 주차 행은 반영 대상에서 제외했습니다.':'전체 기간 행을 검증합니다.'}</div><div class="validation-summary"><span>반영 대상 <b>${rows.length}행</b></span><span class="teal">정상 ${rows.filter(r=>!r.error&&!r.candidates.length).length}행</span><span class="amber">중복 후보 ${rows.filter(r=>r.candidates.length).length}행</span><span class="red">수정 필요 ${rows.filter(r=>r.error).length}행</span></div><article class="panel"><div class="panel-head"><div><h2>반영 전 최종 검토</h2><p>오류 행은 제외됩니다. 상태가 보류인 행은 검증·반영 대상에서 자동 제외됩니다. 중복 후보는 직접 선택하세요.</p></div><button id="back-mapping">← 매핑 수정</button></div><div class="table-wrap"><table><thead><tr><th>원본</th><th>업무 및 검증</th><th>반영 방식</th><th>연결 업무</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${esc(r.sheet)}<small>${r.row}행</small></td><td>${esc(r.input.title)||'(제목 없음)'}<small class="${r.error?'red':r.candidates.length?'amber':'teal'}">${esc(r.error)|| (r.candidates.length?'중복 후보 · 자동 병합하지 않음':'정상')} · ${esc(r.input.assignees.map(a=>a.name).join(', '))}</small></td><td><select data-action="${i}" ${r.error?'disabled':''}>${[['new','신규 등록'],['update','기존 업무 업데이트'],['activity','주간 활동만 추가'],['exclude','제외']].map(([v,n])=>`<option value="${v}" ${(upload.choices?.[r.key]?.action||(r.error||r.candidates.length?'exclude':'new'))===v?'selected':''}>${n}</option>`).join('')}</select></td><td><select data-target="${i}"><option value="">연결 대상 선택</option>${state.works.map(w=>`<option value="${w.id}" ${upload.choices?.[r.key]?.target===w.id?'selected':''}>${r.candidates.some(c=>c.id===w.id)?'★ 후보 · ':''}${esc(w.title)} (${w.id.slice(0,8)})</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div><div class="panel-actions"><button id="errors-download">↓ 검증 결과 CSV</button><button id="commit-upload" class="primary">검증된 선택 행 확정 반영</button></div></article>`;}
function batchHistory(){return `<article class="panel"><div class="panel-head"><h2>업로드 이력</h2><span class="subtle">원본 행 · 반영 방식 보존</span></div><div class="table-wrap"><table><thead><tr><th>파일</th><th>활동일</th><th>반영</th><th>상태</th><th>관리</th></tr></thead><tbody>${[...state.batches].reverse().map(b=>`<tr><td><button class="text-button" data-batch="${b.id}">${esc(b.filename)}</button><small>${esc(b.time.slice(0,16).replace('T',' '))} UTC</small></td><td>${b.completionFrom?esc(b.completionFrom)+" ~ "+esc(b.completionTo):b.period}${b.completionFrom?"<small>과거 완료 일괄 반영</small>":""}</td><td>${b.changes.length}건</td><td>${badge(b.status==='반영완료'?'완료':'취소')}</td><td>${b.status==='반영완료'?`<button class="danger" data-rollback="${b.id}">되돌리기</button>`:'취소 이력 보존'}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">업로드 이력이 없습니다.</td></tr>'}</tbody></table></div></article>`;}
function reportsView(){return `<div class="notice">확정 시점의 지표·문구·원본 업무를 파일에 보존합니다. PPT는 사용자 양식 수령 후 연결할 예정입니다.</div><div class="report-grid">${[...state.reports].reverse().map(r=>`<article class="panel report-card"><div class="report-symbol">▧</div><span class="badge teal">확정 스냅샷</span><h2>${esc(r.title)}</h2><p>${r.filters.from} ~ ${r.filters.to}</p><div class="report-numbers">${r.metrics.total}<small>고유업무</small><span>${r.metrics.rate??'—'}%<small>완료율</small></span></div><button data-report="${r.id}">보고서 열기 →</button></article>`).join('')||'<div class="empty panel">확정된 보고서가 없습니다. 월간 업무현황에서 보고서를 작성해 주세요.</div>'}</div>`;}
function settingsView(){return `<div class="notice">관리자: 이창주 · 직원: 본인 업무 등록·수정 · 팀장: 조회 전용. 신규 계정의 최초 비밀번호는 1입니다.</div><div class="two-col"><article class="panel"><div class="panel-head"><h2>파트 · 직원 마스터</h2></div><div class="form-pad">${state.settings.teams.map(t=>`<label>${t}<input data-people="${t}" value="${esc(state.settings.people[t].join(', '))}"></label>`).join('')}<p class="muted">직원명은 쉼표로 구분합니다. 기존 업무의 담당 당시 파트와 이름은 유지됩니다.</p></div></article><article class="panel"><div class="panel-head"><h2>업무구분</h2></div><div class="form-pad"><textarea id="categories" rows="14">${esc(state.settings.categories.join('\n'))}</textarea><button id="save-settings" class="primary">설정 저장</button></div></article></div><article class="panel"><div class="panel-head"><div><h2>파일 보관 및 백업</h2><p>저장 시 이전 데이터의 백업 파일을 자동 생성합니다.</p></div><a class="button" href="/api/backup" download>↓ 전체 데이터 백업</a></div><div class="storage-box"><code>data/work-data.json</code><span>자동 백업: data/backups/</span><p>복원: 서버를 종료하고 백업 파일을 work-data.json으로 복사한 뒤 재시작합니다. 원본 파일을 먼저 별도 보관하세요.</p></div></article>`;}
function aiView(){return `<article class="panel feature-placeholder"><span class="feature-icon">✦</span><div class="eyebrow">COMING NEXT</div><h2>근거와 함께 작성하는 업무 요약</h2><p>외부 AI 서비스는 연결되어 있지 않습니다.<br>현재는 월간 보고서에서 원본 업무를 참고해 직접 문구를 작성하고 확정할 수 있습니다.</p><button data-nav="월간 업무현황" class="primary">월간 보고서 작성하기 →</button><div class="note">향후 파트별 주요 진행사항, 반복요청과 자동화 후보 추천을 연결할 수 있습니다.</div></article>`;}
function openDialog(html){const d=$('#modal');d.innerHTML=html;d.showModal();d.querySelector('[data-close]')?.addEventListener('click',()=>d.close());d.querySelector('input,button')?.focus();applyModalPermissions();}
function workDialog(w=null){const current=w?state.works.find(a=>a.id===w.id):null;const data=current||{title:'',category:state.settings.categories[0],status:'예정',created:state.today,due:'',completed:'',assignees:state.currentUser.role==='staff'?[{name:state.currentUser.name,team:state.currentUser.team}]:[],description:'',tags:'',kind:'개발업무',reason:''};
 openDialog(`<div class="dialog-head"><div><div class="eyebrow">WORK ITEM ${current?'· '+current.id.slice(0,8):''}</div><h2>${current?'업무 상세 및 수정':'새 업무 등록'}</h2></div><button data-close aria-label="닫기">✕</button></div><form id="work-form"><div class="dialog-body"><label>업무 제목 *<input name="title" required maxlength="300" value="${esc(data.title)}" placeholder="어떤 업무인가요?"></label><div class="form-grid"><label>업무구분<select name="category">${opt([...new Set([...state.settings.categories,data.category])],data.category)}</select></label><label>상태<select name="status">${opt(statuses.filter(s=>s!=='접수'),data.status)}</select></label><label>등록일<input type="date" required name="created" value="${data.created}" ${current?'readonly':''}></label><label>활동·변경일<input type="date" required name="activityDate" value="${state.today}"></label><label>목표일<input type="date" name="due" value="${data.due}"></label><label>완료일<input type="date" name="completed" value="${data.completed}"></label><label>업무유형<select name="kind">${opt(['개발업무','장비지원'],data.kind)}</select></label><label>태그<input name="tags" value="${esc(data.tags)}" placeholder="보안, 모바일"></label></div><label>공동담당 * <span class="subtle">담당 당시 파트를 함께 저장합니다.</span></label><div class="assignee-grid">${state.settings.teams.map(t=>`<fieldset><legend>${t}</legend>${[...new Set([...state.settings.people[t],...data.assignees.filter(a=>a.team===t).map(a=>a.name)])].map(n=>`<label><input type="checkbox" name="assignee" value="${esc(t+'|'+n)}" ${data.assignees.some(a=>a.team===t&&a.name===n)?'checked':''}>${esc(n)}</label>`).join('')}</fieldset>`).join('')}</div><label>업무 내용<textarea rows="4" name="description">${esc(data.description)}</textarea></label><label>변경·보류 사유 <span class="subtle">보류 및 완료 후 재오픈 시 필수</span><input name="reason" value="${esc(data.reason)}"></label>${current?`<details open><summary>상태 변경 이력 · ${current.history.length}건</summary><div class="history">${[...current.history].reverse().map(h=>`<div><span>${h.date}</span>${badge(h.status)}<span>${esc(h.reason)||'—'}</span></div>`).join('')}</div></details><details><summary>주차별 활동 및 원본 · ${current.activities.length}건</summary><div class="history">${[...current.activities].reverse().map(a=>`<div><span>${a.date}</span><div>${esc(a.content)||'활동 기록'}<small>${a.source?`${esc(a.source.filename)} / ${esc(a.source.sheet)} / ${a.source.row}행`:'직접 입력'}</small></div></div>`).join('')}</div></details>`:''}</div><div class="dialog-actions"><span id="form-error" class="red" role="alert"></span><button type="submit" class="primary">${current?'변경 저장':'업무 등록'}</button></div></form>`);
 addWorkFields(data);
 compactWorkLayout();
 applyWorkPermissions(current);
 $('#work-form').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target),input=Object.fromEntries(form);input.assignees=form.getAll('assignee').map(v=>{const [team,name]=v.split('|');return {team,name};});if(current)input.version=current.version;const btn=e.submitter;btn.disabled=true;try{await api(current?'/api/works/'+current.id:'/api/works',current?'PUT':'POST',input);$('#modal').close();await refresh();notify('업무를 파일에 저장했습니다.');}catch(err){$('#form-error').textContent=err.message;}finally{btn.disabled=false;}};
}
function reportDialog(report=null){const flow=report?.flowMetrics||(!report&&period==='month'?periodFlow(state.works,effectiveFilters()):null);const works=report?.works||selected(),m=report?.metrics||metrics(works);openDialog(`<div class="dialog-head"><div><div class="eyebrow">MONTHLY REPORT · ${report?'CONFIRMED':'DRAFT'}</div><h2>${report?'확정 보고서':'월간 보고서 작성'}</h2></div><button data-close>✕</button></div><div class="dialog-body report-print"><label>보고서 제목<input id="report-title" value="${esc(report?.title||filters.from.slice(0,7)+' 전산팀 업무현황')}" ${report?'readonly':''}></label><p class="muted">${esc((report?.filters||filters).from)} ~ ${esc((report?.filters||filters).to)} · 기준일 ${esc((report?.filters||filters).asOf)} · ${esc((report?.filters||filters).basis)}</p>${flow?`<div class="report-stats">전월 이월 <b>${flow.carry}건</b> · 당월 접수 <b>${flow.received}건</b> · 당월 완료 <b>${flow.completed}건</b> · 기준일 미완료 <b>${flow.remaining}건</b></div>`:`<div class="report-stats">고유업무 <b>${m.total}건</b> · 완료 <b>${m['완료']}건</b> · 진행 <b>${m['진행']}건</b> · 완료율 <b>${m.rate??'—'}%</b></div>`}<label>주요 성과 · 이슈 · 다음 달 계획<textarea id="report-content" rows="9" ${report?'readonly':''}>${esc(report?.content||reportDraft||'주요 성과\n\n진행 중 핵심 과제\n\n주요 이슈 및 지원 필요사항\n\n다음 달 계획\n')}</textarea></label><h3>원본 근거 업무</h3>${table(works)}</div><div class="dialog-actions">${report?`<button id="print-report">인쇄 / PDF 저장</button><button id="download-report" class="primary">스냅샷 JSON 다운로드</button>`:'<span class="muted">확정 후 문구와 원본 업무를 스냅샷으로 보존합니다.</span><button id="confirm-report" class="primary">검토 완료 · 보고서 확정</button>'}</div>`);if(report){bindSnapshotEvidence(report);$('#print-report').onclick=()=>window.print();$('#download-report').onclick=()=>download(report,`보고서-${report.id.slice(0,8)}.json`);}else $('#confirm-report').onclick=()=>safe(async()=>{const title=$('#report-title').value,content=$('#report-content').value;reportDraft=content;await api('/api/reports','POST',{title,content,filters:effectiveFilters()});$('#modal').close();page='보고서 보관함';await refresh();notify('보고서를 확정하고 파일에 저장했습니다.');});}
function download(value,name,type='application/json'){const blob=new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function toCSV(rows){return '\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');}
async function safe(fn){if(busy)return;busy=true;document.body.classList.add('busy');try{await fn();}catch(e){if(e.status===401){state=null;$('#modal').close();await loginView();}else notify(e.message,true);}finally{busy=false;document.body.classList.remove('busy');}}
function navigate(name){if(name==='주간 업무현황'||name==='월간 업무현황'){setPeriod(name==='월간 업무현황'?'month':'week');name='업무현황';}if(name!=='업무 목록'&&period==='year')setPeriod('month');page=name;workAssignee='';search='';statusFilter='';if(name==='업무현황'&&!['week','month'].includes(period))setPeriod('week');if(name==='주간 업무현황')setPeriod('week');if(name==='월간 업무현황')setPeriod('month');render();window.scrollTo(0,0);}
