function bindSnapshotEvidence(report){
 document.querySelectorAll('#modal [data-work]').forEach(button=>button.onclick=()=>{
  const w=report.works.find(w=>w.id===button.dataset.work);
  openDialog(`<div class="dialog-head"><h2>확정 시점 원본 업무</h2><button data-close>✕</button></div><div class="dialog-body"><h3>${esc(w.title)}</h3><p>${badge(w.status)}</p><p>${esc(w.description)}</p><p class="muted">${esc(w.id)} · ${esc(w.assignees.map(a=>a.team+' / '+a.name).join(', '))}</p><div class="history">${w.activities.map(a=>`<div><span>${a.date}</span><span>${esc(a.content)}<small>${a.source?esc(a.source.filename)+' / '+esc(a.source.sheet)+' / '+a.source.row+'행':'직접 입력'}</small></span></div>`).join('')}</div></div>`);
 });
}
function addWorkFields(data){
 $('#work-form .form-grid').insertAdjacentHTML('beforeend',`<label>시작일<input type="date" name="started" value="${esc(data.started||'')}"></label><label>진행률 (%)<input type="number" min="0" max="100" step="1" name="progress" placeholder="미입력" value="${data.progress??''}"></label><label>요청부서<input name="requestDept" maxlength="100" value="${esc(data.requestDept||'')}" placeholder="예: 외래 간호팀"></label><label>장비 종류<select name="equipmentType">${opt(['PC','프린터','모니터','바코드프린터','서버','소프트웨어','네트워크','기타'],data.equipmentType,'미분류 / 해당 없음')}</select></label>`);
 const status=$('#work-form [name="status"]'),progress=$('#work-form [name="progress"]');
 status.addEventListener('change',()=>{if(status.value==='완료')progress.value='100';else if(progress.value==='100')progress.value='';});
}
function compactWorkLayout(){
 const dialog=$('#modal'),form=$('#work-form'),body=form.querySelector('.dialog-body'),grid=form.querySelector('.form-grid');
 dialog.classList.add('work-detail-dialog');
 for(const name of ['category','status','kind','progress','requestDept','equipmentType','created','started','due','completed','activityDate','tags']){const label=form.querySelector(`[name="${name}"]`)?.closest('label');if(label)grid.append(label);}
 const notes=document.createElement('div');notes.className='work-notes';
 const description=form.querySelector('[name="description"]').closest('label'),reason=form.querySelector('[name="reason"]').closest('label');
 description.before(notes);notes.append(description,reason);
 const details=[...body.querySelectorAll(':scope > details')];
 if(details.length){const histories=document.createElement('div');histories.className='work-history-grid';body.append(histories);for(const detail of details){detail.open=false;histories.append(detail);}}
}
