function noticeDialog(n=null){
 openDialog(`<div class="dialog-head"><div><div class="eyebrow">TEAM NOTICE</div><h2>${n?'공지 상세 및 수정':'새 공지 등록'}</h2></div><button data-close aria-label="닫기">✕</button></div><form id="notice-form"><div class="dialog-body"><label>제목<input name="title" required maxlength="150" value="${esc(n?.title||'')}" placeholder="팀에 전달할 내용을 입력하세요"></label><div class="form-grid"><label>구분<select name="category">${opt(['공지','안내','이슈'],n?.category||'공지')}</select></label><label>표시 상태<select name="archived"><option value="false">게시</option><option value="true" ${n?.archived?'selected':''}>보관</option></select></label></div><label>내용<textarea name="content" rows="8" required maxlength="10000">${esc(n?.content||'')}</textarea></label><label class="checkbox-label"><input type="checkbox" name="pinned" ${n?.pinned?'checked':''}>상단 고정</label>${n?'<p class="muted">최초 게시일 '+esc(n.date)+' · 버전 '+n.version+'</p>':''}</div><div class="dialog-actions"><span class="muted">내용은 이 PC의 JSON 파일에 저장됩니다.</span><button type="submit" class="primary">공지 저장</button></div></form>`);
 $('#notice-form').onsubmit=e=>{e.preventDefault();safe(async()=>{const data=Object.fromEntries(new FormData(e.target));data.pinned=e.target.elements.pinned.checked;data.archived=data.archived==='true';if(n)data.version=n.version;await api(n?'/api/notices/'+n.id:'/api/notices',n?'PUT':'POST',data);$('#modal').close();await refresh();notify('공지사항을 파일에 저장했습니다.');});};
}

function excelSettingsPanel(){
 const saved=state.settings.excelMapping||{header:1,map:{title:0,assignees:1,status:2,category:3,created:4,completed:5,description:6,reason:-1,externalId:-1},assigneeSource:'column',statusText:'',kind:'개발업무'};
 return `<article class="panel"><div class="panel-head"><div><h2>엑셀 공통 매핑 사전 설정</h2><p>개발자별 양식이 같으면 여기서 한 번 저장하세요. 모든 시트·다음 업로드에 공통 적용됩니다.</p></div><button id="save-excel-settings" class="primary">공통 매핑 저장</button></div><div class="form-pad"><div class="common-mapping-heading"><label>공통 헤더 행<input id="preset-header" type="number" min="1" max="20000" value="${saved.header}"></label><label>담당자 확인<select id="preset-assignee-source">${[['column','담당자 컬럼 사용'],['sheet','시트명 = 직원명']].map(([v,n])=>`<option value="${v}" ${saved.assigneeSource===v?'selected':''}>${n}</option>`).join('')}</select></label><label>업무 유형<select id="preset-kind">${opt(['개발업무','장비지원'],saved.kind)}</select></label></div><div class="mapping-grid">${fields.filter(([key])=>key!=='team').map(([key,label])=>`<label>${label}<select data-preset-map="${key}"><option value="-1">연결 안 함</option>${Array.from({length:150},(_,i)=>`<option value="${i}" ${saved.map[key]===i?'selected':''}>${i+1}열 (${excelColumn(i)})</option>`).join('')}</select></label>`).join('')}</div><label class="preset-status">추가 상태 매핑<input id="preset-status" value="${esc(saved.statusText)}" placeholder="처리중=진행, 대기=접수"></label><div class="notice mapping-notice">파트는 위의 직원 마스터 소속으로 자동 반영합니다. 담당자 컬럼이 없는 개인 시트는 ‘시트명 = 직원명’을 선택하세요.<br>개발중→진행, 처리완료→완료는 기본 적용됩니다. 저장된 매핑은 다음 파일을 선택할 때 자동으로 불러옵니다.</div></div></article>`;
}
function excelColumn(i){let result='';for(i++;i>0;i=Math.floor((i-1)/26))result=String.fromCharCode(65+(i-1)%26)+result;return result;}
function bindExcelSettings(){
 for(const [id,checked] of [["select-all-sheets",true],["clear-all-sheets",false]])if($("#"+id))$("#"+id).onclick=()=>{document.querySelectorAll("[data-sheet]").forEach(e=>e.checked=checked);collectMapping();render();};
 if($('#save-excel-settings'))$('#save-excel-settings').onclick=()=>safe(async()=>{const mapping={header:Number($('#preset-header').value),map:Object.fromEntries([...document.querySelectorAll('[data-preset-map]')].map(e=>[e.dataset.presetMap,Number(e.value)])),assigneeSource:$('#preset-assignee-source').value,kind:$('#preset-kind').value,statusText:$('#preset-status').value};await api('/api/settings/excel-mapping','PUT',mapping);await refresh();notify('모든 개발자에 적용할 공통 매핑을 저장했습니다.');});
 if($('#save-upload-mapping'))$('#save-upload-mapping').onclick=()=>safe(async()=>{collectMapping();const result=await api('/api/settings/excel-mapping','PUT',{header:upload.commonHeader,map:upload.commonMap,assigneeSource:upload.assigneeSource,kind:upload.kind,statusText:upload.statusText});state.settings.excelMapping=result.mapping;notify('현재 공통 매핑을 관리자 설정에 저장했습니다.');});
 document.querySelectorAll('[data-sheet]').forEach(e=>e.onchange=()=>{collectMapping();render();});
}

function monthlyHighlightsTable(works){
 const teams=filters.team?[filters.team]:state.settings.teams;
 const rows=monthlyHighlights(works,teams,filters);
 return `<article class="panel"><div class="panel-head"><div><h2>파트별 주요내용 <span class="teal">${rows.length}건</span></h2><p>빨간 제목 업무 우선 · 파트별 최대 3건, 전체 15건 이내 · 부족한 경우 일반 업무 보완</p></div></div><div class="table-wrap"><table class="monthly-highlights"><thead><tr><th>파트</th><th>주요 업무</th><th>주요내용</th><th>담당자</th><th>상태</th></tr></thead><tbody>${rows.map(({team,work:w,summary})=>`<tr><td><span class="team-tag team-${esc(team)}">${esc(team)}</span></td><td><button class="work-title ${w.isMajor?'red':''}" data-work="${w.id}">${esc(w.title)}</button><small>${w.isMajor?'● 엑셀 빨간 제목':'일반 업무 보완'}</small></td><td class="highlight-summary">${esc(summary)||'상세 내용 미입력 · 업무 제목을 확인하세요.'}</td><td>${esc(w.assignees.filter(a=>a.team===team).map(a=>a.name).join(', '))}</td><td>${badge(w.status)}</td></tr>`).join('')||'<tr><td class="empty" colspan="5">선택한 월·파트에 해당하는 업무가 없습니다.</td></tr>'}</tbody></table></div><p class="highlights-footnote">공동담당 업무는 참여 파트별로 표시될 수 있습니다. 업무명을 누르면 원본 및 활동 이력을 확인할 수 있습니다.</p></article>`;
}

function annualFilterBar(){
 const year=dashboardYear||state.today.slice(0,4),current=Number(state.today.slice(0,4));
 const years=[...new Set([current,...state.works.map(w=>Number(w.created.slice(0,4))).filter(y=>y>=1900),Number(year)])].sort((a,b)=>b-a);
 const range=yearRange(year,state.today);
 return `<div class="filter-bar"><label class="month-picker">조회 연도<select id="dashboard-year" aria-label="조회 연도">${years.map(y=>`<option value="${y}" ${String(y)===year?'selected':''}>${y}년</option>`).join('')}</select></label><label class="part-filter-label">파트구분 <select id="team" aria-label="파트 필터">${opt(partOptions,filters.team,'전체선택')}</select></label><span class="flow-basis">연간 접수·완료일 기준 / 미완료는 기준일 상태</span><button class="text-button" data-nav="업무현황">주간·월간 상세 보기 →</button></div><div class="criteria"><span>${range.from} ~ ${range.to} · 상태 기준일 ${range.asOf} · 이전 연도 미완료 이월 포함</span><span>연간 전체 현황</span></div>`;
}

function workAssigneeSelect(){
 const members=new Map();
 for(const team of state.settings.teams.filter(t=>!filters.team||t===filters.team))for(const name of state.settings.people[team]||[])members.set(team+'|'+name,{team,name});
 for(const w of state.works)for(const a of w.assignees.filter(a=>!filters.team||a.team===filters.team))members.set(a.team+'|'+a.name,a);
 return `<label class="assignee-filter">담당자<select id="work-assignee" aria-label="담당자 필터"><option value="">전체선택</option>${[...members].map(([key,a])=>`<option value="${esc(key)}" ${key===workAssignee?'selected':''}>${esc(a.name)}${filters.team?'':' · '+esc(a.team)}</option>`).join('')}</select></label>`;
}

function workYearSelect(){
 const selected=filters.from.slice(0,4),current=Number(state.today.slice(0,4));
 const years=[...new Set([current,Number(selected),...state.works.map(w=>Number(w.created.slice(0,4))).filter(y=>y>=1900)])].sort((a,b)=>b-a);
 return `<label class="month-picker">조회 연도<select id="work-year" aria-label="업무목록 조회 연도">${years.map(y=>`<option value="${y}" ${String(y)===selected?'selected':''}>${y}년</option>`).join('')}</select></label>`;
}

function roleName(role){return role==='admin'?'관리자':role==='leader'?'팀장 · 조회 전용':'담당자';}
async function loginView(){
 const result=await api('/api/auth/users');
 $('#app').innerHTML=`<div class="login-page"><div class="login-page-title"><span class="login-title-mark">IT</span><div>일산전산팀 업무관리<small>ILSAN IT WORKSPACE</small></div></div><section class="login-intro"><div class="login-brand"><span class="brandmark">IT<span>✦</span></span>IT WORKSPACE</div><div class="login-kicker">OPERATIONS / CONNECTED</div><h1>업무의 흐름을 연결하는<br><em>전산팀 워크스페이스</em></h1><p>업무 기록과 진행 현황, 주간·월간 보고를<br>하나의 공간에서 관리하세요.</p><div class="network-visual"><i></i><i></i><i></i><i></i><span>WORK</span><b>DATA</b><small>INSIGHT</small></div><div class="login-caption"><span></span> LOCAL WORKSPACE · FILE STORAGE</div></section><section class="login-card"><div class="login-card-brand"><span class="login-emblem">IT</span><div>WORKSPACE<sup>+</sup><small>일산차병원 전산팀 업무관리</small></div></div><h2>스마트 로그인</h2><p>안전하고 편리한 업무관리를 위한 로그인</p><form id="login-form"><label>성명<select name="name" required aria-label="로그인 성명"><option value="">이름을 선택하세요</option>${result.users.map(u=>`<option value="${esc(u.name)}">${esc(u.name)} · ${esc(u.team)}${u.role==='leader'?' (팀장)':''}</option>`).join('')}</select></label><label>비밀번호<input name="password" type="password" required maxlength="128" autocomplete="current-password" placeholder="비밀번호 입력"></label><div id="login-error" role="alert"></div><button type="submit" class="primary">로그인 →</button></form><div class="login-help">최초 비밀번호는 <b>1</b>입니다.<br>로그인 후 본인 비밀번호를 변경할 수 있습니다.</div><small>IT WORKSPACE · 전산팀 업무관리</small></section></div>`;
 $('#login-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;$('#login-error').textContent='';try{await api('/api/auth/login','POST',Object.fromEntries(new FormData(e.target)));page='대시보드';await refresh();}catch(error){$('#login-error').textContent=error.message;button.disabled=false;}};
}
function passwordDialog(){
 openDialog(`<div class="dialog-head"><h2>본인 비밀번호 변경</h2><button data-close aria-label="닫기">✕</button></div><form id="password-form"><div class="dialog-body password-fields"><p>${esc(state.currentUser.name)} 님의 비밀번호를 변경합니다.</p><label>현재 비밀번호<input name="currentPassword" type="password" autocomplete="current-password" required maxlength="128"></label><label>새 비밀번호<input name="newPassword" type="password" autocomplete="new-password" required maxlength="128"></label><label>새 비밀번호 확인<input name="confirm" type="password" autocomplete="new-password" required maxlength="128"></label><p id="password-error" class="red" role="alert"></p></div><div class="dialog-actions"><span class="muted">변경하면 다른 로그인 세션은 종료됩니다.</span><button type="submit" class="primary">비밀번호 변경</button></div></form>`);
 $('#password-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target)),button=e.submitter;if(data.newPassword!==data.confirm){$('#password-error').textContent='새 비밀번호 확인이 일치하지 않습니다.';return;}button.disabled=true;try{await api('/api/auth/password','POST',data);$('#modal').close();await refresh();notify('비밀번호를 변경했습니다.');}catch(error){$('#password-error').textContent=error.message;button.disabled=false;}};
}
function accountSettingsPanel(){return `<article class="panel"><div class="panel-head"><div><h2>사용자 · 퇴사 여부 · 비밀번호 관리</h2><p>퇴사자는 로그인 목록에서 제외됩니다. 기존 업무 이력과 통계는 유지됩니다.</p></div><button id="save-personnel" class="primary">인사설정 저장</button></div><div class="personnel-leader"><label>팀장 이름<input id="team-leader-name" maxlength="50" value="${esc(state.settings.teamLeaderName||'')}" placeholder="팀장 이름을 입력하세요"></label><p>저장하면 팀장 로그인 계정이 생성됩니다. 신규 계정의 최초 비밀번호는 1이며 조회 전용입니다.</p></div><div class="table-wrap"><table><thead><tr><th>성명</th><th>파트</th><th>권한</th><th>퇴사 여부</th><th>비밀번호 초기화</th></tr></thead><tbody>${state.accounts.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.team)}</td><td>${roleName(u.role)}</td><td><label class="checkbox-label"><input type="checkbox" data-departed="${esc(u.name)}" aria-label="${esc(u.name)} 퇴사 여부" ${u.departed?'checked':''} ${u.role==='admin'?'disabled':''}>퇴사</label></td><td><button data-password-reset="${esc(u.name)}" ${u.departed?'disabled':''}>1로 초기화</button></td></tr>`).join('')}</tbody></table></div></article>`;}
function resetPasswordDialog(name){openDialog(`<div class="dialog-head"><h2>비밀번호 초기화</h2><button data-close>✕</button></div><div class="dialog-body"><p>${esc(name)} 님의 비밀번호를 <b>1</b>로 초기화합니다.</p><p class="muted">해당 사용자의 기존 로그인은 종료됩니다.</p></div><div class="dialog-actions"><button id="confirm-password-reset" class="primary">초기화 실행</button></div>`);$('#confirm-password-reset').onclick=()=>safe(async()=>{await api('/api/auth/reset','POST',{name});$('#modal').close();await refresh();notify('비밀번호를 1로 초기화했습니다.');});}
function applyPermissions(){
 const role=state.currentUser.role;
 for(const selector of ['#upload-nav','#create-report','#new-notice','#demo','[data-rollback]'])if(role!=='admin')document.querySelectorAll(selector).forEach(e=>{e.disabled=true;e.title='관리자 전용 기능';});
 if(role==='leader'){$('#new-work').disabled=true;$('#new-work').title='팀장은 조회 전용입니다.';}
}
function applyWorkPermissions(current){
 const user=state.currentUser,readOnly=user.role==='leader'||user.role==='staff'&&current&&!current.assignees.some(a=>a.name===user.name);
 if(readOnly){document.querySelectorAll('#work-form input,#work-form select,#work-form textarea,#work-form button[type=submit]').forEach(e=>e.disabled=true);$('#form-error').textContent=user.role==='leader'?'팀장 계정은 조회 전용입니다.':'다른 담당자의 업무는 조회만 가능합니다.';}
}
function applyModalPermissions(){
 const dialog=$('#modal');if(!state?.currentUser||dialog.querySelector('#password-form'))return;
 const readonly=state.currentUser.role==='leader'||state.currentUser.role!=='admin'&&dialog.querySelector('#notice-form');
 if(readonly){dialog.querySelectorAll('input,select,textarea,button[type=submit],#confirm-report,#confirm-rollback,#confirm-password-reset').forEach(e=>{e.disabled=true;e.title='조회 전용';});}
}
